        timur_endLight: { text: 'तरुण अजनबियों की नज़रों के सामने आगे बढ़ा। उसी रात उसने गिरोह के एक और सरगना के साथ मिलकर अपना चाक़ू उपदेशक को सौंप दिया, बदले में एक बाइबल ली — यह इशारा उसके लिए पुरानी ज़िंदगी के अंत का प्रतीक बना। अगले तीन साल उसने बाइबल कॉलेज में बिताए, जहाँ उसकी होने वाली पत्नी से मुलाक़ात हुई; अपने शहर लौटकर उसने मुश्किल किशोरों के लिए देश का पहला पुनर्वास केंद्र खुद खड़ा किया, वही जिसे उस उपदेशक ने शुरू किया था। उस रात एक ज़िंदगी ख़त्म हुई और दूसरी शुरू हुई — कमर में चाक़ू नहीं, पीठ पीछे गिरोह नहीं, पर वह अकेलापन भी नहीं जो पहले ताक़त के पीछे छुपा रहता था। सालों बाद उसने इस पर एक किताब लिखी, अपनी मिशनरी सेवा शुरू की और आज वह अपने जैसे गली के किशोरों से मिलने जाता है — सिर्फ़ अपने पुराने इलाक़े में नहीं, बल्कि दर्जनों देशों में — उन्हें वही बात कहते हुए जो कभी उसे किसी ने कही थी। तरुण की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
        timur_endDark: { text: 'तरुण मुड़कर वापस गली में चला गया, उसी आँगन और उसी ख़ामोशी में जो उसे किसी भी गिरोह से ज़्यादा डराती थी। उसे अक्सर उस दोस्त के आख़िरी शब्द याद आते जो उसकी बाहों में मर गया था, पर वह कभी अपनी ज़िंदगी बदलने की हिम्मत नहीं जुटा पाया। कुछ साल बाद उसका नाम फिर ख़बरों में आया — अब किसी सरगना के नाम से नहीं, बल्कि इलाक़े की अपराध रिपोर्ट की एक और लाइन के तौर पर, बिना यह बताए कि वह सच में क्या बन सकता था। तरुण की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
