        grisha_bridgeA: { text: 'गिरीश ने जवाब दिया — पहले सलाखों के आर-पार एक छोटा शब्द, फिर एक वाक्य, फिर पूरी तरह किसी और विषय पर एक बातचीत। रातों को, जब साथी क़ैदी सो जाते, वह चुपके से पादरी की छोड़ी हुई बाइबिल खोलता और गलियारे से आती रोशनी में कुछ पंक्तियाँ पढ़ता, फिर, अपने जीवन में पहली बार, धीमी आवाज़ में, अनाड़ी ढंग से, प्रार्थना जैसा कुछ कहने की कोशिश करता। महीनों बाद उसने सालों में पहली बार उस लड़ाई के बारे में और उस आदमी के चेहरे के बारे में ज़ोर से बात की जिसकी जान उसने एक ही वार में ले ली थी। पादरी को इस बदलाव पर न आश्चर्य हुआ, न उसने जज किया, बस हमेशा की तरह हर हफ़्ते आता रहा, मानो यह पहले से ही तय था। ऐसी ही एक रात, कोठरी में बिल्कुल अकेला रह जाने पर, गिरीश को अचानक बचपन में दादा के कहे शब्द याद आए: एक दिन ऐसा आएगा जब यीशु मसीह के सिवा कोई मदद नहीं कर पाएगा। ठीक तभी, अपने जीवन में पहली बार, किताब से नहीं बल्कि अपने ही शब्दों में, उसने ज़ोर से ईश्वर को पुकारा।', next: 'grisha_choice2' },
        grisha_bridgeB: { text: 'गिरीश लगातार महीनों चुप रहा, लेकिन ख़ुद उसने नोटिस किया कि चुप्पी के बावजूद पादरी ने आना नहीं छोड़ा — और यह लगातार आते रहना अपने आप में किसी भी शब्द से ज़्यादा उसे सोचने पर मजबूर करता।', next: 'grisha_choice2' },
        grisha_choice2: { text: 'आने वाले सालों में — देश की चार अलग-अलग जेलों में, क़रीब बारह साल सलाखों के पीछे रहते हुए — गिरीश ने बाइबिल लगभग पूरी याद कर ली और एक से ज़्यादा बार ख़ुद सलाखों के पास बैठकर, नए आए, उतने ही डरे हुए किशोरों के साथ, वही शब्द दोहराए जो कभी पादरी ने उससे कहे थे। इन क़रीब बारह सालों में से लगभग पूरा समय उसने कई सख़्त सुरक्षा वाली जेलों में बिताया, देश की सबसे बड़ी जेल सहित, और आख़िरकार राष्ट्रपति के क्षमादान आदेश ने उसे आज़ादी लौटाई। रिहाई से पहले, गिरीश को जेल के चर्च में स्वयंसेवक के रूप में रुकने का प्रस्ताव मिलता है — उसी जगह वापस जहाँ वह ख़ुद क़ैद था, लेकिन अब सलाखों के दूसरी तरफ़ से, सज़ा से नहीं, अपनी मर्ज़ी से, और इस काम के लिए एक भी पैसा तनख़्वाह नहीं।', choices: [
          { label: 'रुक जाना और अपनी ज़िंदगी उन लोगों को समर्पित करना जो उसका रास्ता तय कर रहे हैं', effects: { faith: 15 }, next: 'grisha_endLight' },
          { label: 'जितना हो सके दूर चले जाना और कभी पीछे मुड़कर जेल की ओर न देखना', effects: { faith: -15 }, next: 'grisha_endDark' },
        ] },
        grisha_endLight: { text: 'गिरीश रुक गया। चालीस से ज़्यादा साल बाद भी वह उन्हीं कोठरियों की क़तारों में जाता है जहाँ पादरी कभी किशोर गिरीश से मिलने आता था — बस अब सलाखों की उस तरफ़ से जहाँ उसकी ज़रूरत है, हर हफ़्ते बिना चूके, इन सारे दशकों तक, और देशभर के दर्जनों पूर्व क़ैदी उसे ही वह इकलौता इंसान बताते हैं जिसने पहला मुँह नहीं मोड़ा, जब बाक़ी सब उन्हें कब का बेकार मान चुके थे। गिरीश की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        grisha_endDark: { text: 'गिरीश चला गया और जेल की याद दिलाने वाली हर चीज़ से, पुराने नाम और पते सहित, जितना हो सके दूर एक नई ज़िंदगी बनाई। उसने फिर कभी ज़ोर से अतीत की बात नहीं की, किसी से नहीं, सोने से पहले ख़ुद से भी नहीं। गिरीश की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
