        lyuda_endLight: { text: 'लता मान गई। जिस सेवा को बनाने में उसने मदद की, उसने पहले ही साल में तीस से ज़्यादा परिवारों को इकट्ठा किया, हर एक परिवार सालों तक ठीक वैसे ही घरों में छिपा रहा था जैसे कभी वह ख़ुद मोहन और रोहन के साथ छिपी थी। सालों बाद, बड़े हो चुके दोनों बेटों ने ख़ुद उसी मंडली में अपनी स्थायी जगह पा ली — एक सेवा से पहले द्वार पर लोगों का स्वागत करता है, दूसरा साउंड में मदद करता है — और दोनों, अपने-अपने तरीक़े से, चर्च के लिए उतने ही ज़्यादा ज़रूरी साबित हुए जितना उनके तीन साल की उम्र में स्पीच थेरेपिस्ट के दफ़्तर में कोई सोच भी नहीं सकता था। लता की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        lyuda_endDark: { text: 'लता ने मना कर दिया, पूरी मंडली के सामने अपने बेटों को दिखाने से डरते हुए। वह दोनों लड़कों को बाक़ी सबसे अलग पालती रही, और उनके पहले शब्दों वाली कॉपी मेज़ की दराज़ में अधूरी ही पड़ी रह गई — सालों बाद उसने माना कि उसे बेटों के दोहरे निदान का नहीं, बल्कि उन सालों का अफ़सोस है जब उसने दोनों को उन लोगों से छुपाए रखा जो शायद उन्हें वैसे ही अपना लेते जैसे वे थे। लता की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
